from model import *

c=C(1,'系统概述','第一篇  系统总体设计')
S(c,'系统定位与应用范围',
P('电子飞行包的业务定位','''本系统以 A330-941 为机型对象，把航班计划、载荷燃油、性能辅助计算、运行资料和检查单组织在同一平板界面中。航班是业务组织单元：用户先建立航班，再填写载荷和环境条件，随后在不同页面使用同一组已确认的计划数据。系统由此减少跨页面重复输入，并使计算结果能够追溯到产生它的输入。

系统界面沿用 Headwind A339X 的 flyPad 结构。左侧工具栏选择业务域，页面上方的标签选择该业务域内的功能；状态栏承载时间、连接、电量和快捷控制。新增的本地航班工作台及离线参考计算位于原有签派、性能模块内，因此用户不必在两个彼此独立的软件间切换。

本地交付采用浏览器运行形态，适用于软件开发、技术演示和模拟训练软件的功能研究。当前输入以手工资料、JSON 文件及本地宿主样例为主。真实飞机状态、机场权威数据和商业航图属于其他数据域，通过相应适配接口进入系统。''',diagram=D('context','电子飞行包与使用环境', ['使用者\n航班准备与资料查阅','A330 EFB\n计划 · 计算 · 资料','本机文件\nJSON / HTML','模拟器宿主\n状态与控制','外部资料服务\n航图 / 气象'],[(0,1,'录入与浏览'),(2,1,'导入'),(1,2,'导出'),(3,1,'状态'),(1,3,'请求'),(4,1,'资料')]),table=T('业务对象|系统处理|使用结果','航班计划|建立统一输入快照|航班摘要与签派资料\n载荷燃油|质量汇总与目标映射|ZFW、TOW 和地面目标\n性能辅助|计算器调用与结果管理|参考速度、TOD、着陆显示\n运行资料|分类浏览与状态保存|航图、检查单与设置')),
P('业务边界与系统责任','''系统中同时存在计划、目标和当前状态。计划表示用户准备执行的航班；目标表示用户希望宿主达到的装载或设备状态；当前状态表示宿主最近一次提供的观测。三者有时数值相同，但其含义和生命周期不同。例如，停机坪计划油量为 30000 kg，并不意味着正在连接的飞机已经具有该油量。

EFB 负责收集输入、执行本地规则、显示计算结果及组织操作入口。模拟器负责飞机运动、电气、燃油输送和地面设备的物理过程。性能资料包负责提供与机型、发动机及版本相匹配的数据。把这些责任分开后，界面更换宿主不需要重写航班文件格式，性能资料更新也不需要改变工具栏结构。

当前浏览器宿主提供变量读写和事件接口的开发替身，其作用是让原生页面可以运行。该替身没有实现飞机物理模型。设计说明中的“指令发送”“状态刷新”分别描述软件交互，不自动延伸为真实加油、推回或故障效果。''',table=T('层次|承担的责任|典型内容','界面层|组织输入、导航及反馈|航班表单、状态栏、结果卡片\n领域层|计算及业务状态转换|重量公式、确认签名、参考插值\n数据层|记录计划、结果及版本|Flight、Result、机型资料包\n宿主适配层|转换读写与事件语义|SimVar、Coherent、更新事件\n模拟器|提供实际系统和物理过程|油箱状态、位置、舱门和电源\n外部资料|提供有来源的内容|天气、机场、航图及账户授权'),diagram=D('lanes','计划、目标与观测的关系',[['计划域','航班输入','确认快照','计算输入'],['控制域','目标油量','请求发送','宿主处理'],['观测域','宿主采样','当前油量','界面显示']])) ,
P('运行形态及其适用边界','''同一套 EFB 前端可以部署在模拟器仪表 WebView 中，也可以部署在普通浏览器中。两者共享页面和业务逻辑，差异集中在宿主 API、资源路径和数据来源。浏览器版通过本机静态服务提供页面、字体及机型配置；MSFS 环境由模拟器装载仪表并注入运行接口。

本机版本的核心航班流程不依赖 SimBrief。原生 Store 中仍有名为 simbrief 的兼容切片，但该名称描述历史数据结构，不能据此判断数据来自在线服务。本地确认动作把手工计划转换到该结构，使仪表盘、OFP、燃油和载重页面继续使用既有组件。

扩展到其他机型时，首先变化的是资料包与宿主映射。A330-941 使用的质量上限、座位布局、发动机标识和速度表不能被当作 A330 系列全部型号的公共参数。软件框架可以复用，机型数据和计算适用范围必须保留独立身份。''',table=T('项目|本地浏览器形态|模拟器仪表形态','页面装载|127.0.0.1 静态 HTTP 服务|模拟器仪表资源系统\n变量来源|本机 Map 及样例值|模拟器变量与机载系统\n持久化|当前浏览器站点存储|模拟器数据存储接口\n地面操作|目标和请求交互|由宿主驱动实际过程\n核心航班输入|手工与 JSON 文件|可沿用同一领域模型\n外部后端|尚未连接|取决于已集成宿主'),diagram=D('layers','共用前端与不同宿主',['共用业务：航班 / 性能 / 检查单 / 资料','共用界面：工具栏 / 标签 / 表单 / 结果','接口分界：变量 / 事件 / 文件 / 持久化','本地浏览器宿主    |    MSFS 或其他模拟器宿主'])) ,refs=['HW','FBW','L-F','L-S','L-H'])

S(c,'功能结构与典型业务场景',
P('功能域的组织方式','''系统功能按业务对象划分，而不按底层库或通信协议划分。用户看到的签派、地面和性能是稳定的业务入口；React、Redux、SimVar 等技术名词留在实现内部。一个业务域可以使用多个技术服务，一个技术服务也可以为多个业务域共享。

签派域管理本地航班及其可读资料。地面域管理燃油、载重、设备与推回。性能域包含本地起飞参考、下降顶点和着陆计算。资料域包括航图与在线管制信息；程序域包括检查单、故障、预设和系统设置。各域通过共享航班和宿主数据建立联系，不通过复制整套表单保持一致。

仪表盘是聚合视图。它显示已确认航班、天气、固定航图和检查单入口，但不承担全部数据编辑。聚合页面保持简洁，完整编辑在专门工作台进行，减少一个页面同时出现过多录入规则和计算规则的情况。''',diagram=D('tree','功能分解树',['A330 EFB',['仪表盘','航班摘要','资料与提醒'],['签派','本地航班','OFP / 机型概览'],['地面','燃油 / 载重','服务 / 推回'],['性能','离线参考','TOD / 着陆'],['程序与资料','航图 / 管制','检查单 / 故障 / 设置']]),table=T('功能域|主要输入|主要输出','签派|航班、载荷、燃油|确认计划与 OFP\n地面|已确认计划、宿主状态|目标值及请求状态\n性能|重量、跑道、天气、构型|计算结果和解释信息\n程序资料|配置、资料服务、用户勾选|可浏览资料及执行状态')),
P('从航班准备到结果归档','''一次本地航班准备从工作台开始。用户输入机场、日期、人数和质量后，界面立即显示载荷、ZFW 与 TOW；这些数值是草稿的派生值，不代表计划已经确认。保存确认使当前输入形成稳定的确认签名，并同步到原生页面。

进入起飞参考页后，用户补充跑道、风、气温、气压与构型。计算器先判断数据是否合法，再判断是否在资料包支持范围内，最后生成包含输入快照和版本号的结果对象。界面显示的数值与报告使用同一对象，避免“屏幕是一版、导出又算一版”的差异。

归档保存的是当时的结果及输入。恢复历史时只恢复输入，不把历史结果直接当作当前有效结果。原因是资料包、输入或地面目标可能已变化；重新确认与计算让当前结果重新建立可解释的来源关系。''',diagram=D('sequence','本地航班到报告的交互时序',['使用者','航班状态','计算服务','原生页面'],[(0,1,'编辑草稿'),(0,1,'保存并确认'),(1,3,'映射航班和目标'),(0,2,'请求本地计算'),(2,1,'写入结果与快照'),(0,1,'保存历史 / 导出')]),table=T('阶段|数据状态|用户可见反馈','编辑|草稿变化，确认签名清空|重量卡片更新\n确认|签名与当前输入一致|确认成功提示\n计算|结果带输入与版本|参考结果或原因说明\n归档|本机历史新增一条|最多保留 20 条\n恢复|重新形成草稿|需要重新确认与计算')),
P('离线与外部资料并存的场景','''离线能力来自明确的数据依赖。航班表单、重量公式、已随包部署的速度参考表和检查单配置可以在本机处理；商业航图、网络管制信息和在线天气则需要相应服务。系统把两类能力分开组织，因此资料服务不可达时，航班编辑和本地计算仍可继续。

外部资料页面的空态具有业务含义。未登录、没有订阅、没有固定航图和服务不可用是不同状态，界面不应以同一个空白区域表示全部情况。原生页面具备哪些状态显示取决于对应模块；本地使用说明按实际画面解释这些状态。

网络恢复后，外部资料可以重新获取，而已经保存的本地航班不会因此被自动替换。数据更新的主动权仍在当前业务流程中：在线天气或机场资料作为输入来源时，需要保持来源、时间及单位，不能只把一个新数值写进现有计算结果。''',table=T('使用场景|可在本地完成|需要外部条件','无账号航班准备|手工录入、重量核算、文件往返|无\n本地性能研究|V2 表插值及辅助量|已部署资料包\n程序练习|查看与手动勾选检查单|配置已装载\n航图查阅|浏览页面与已有状态|航图服务、账户或本地资料服务\n在线管制信息|打开对应页面|网络数据源\n飞机系统联动|显示请求及目标|真实模拟器状态接口'),diagram=D('components','离线核心与在线资料的依赖隔离',['本地航班','纯函数计算','本机持久化','航图与气象页面','外部服务适配','网络服务'],[(0,1,'输入'),(0,2,'保存'),(1,2,'结果'),(3,4,'请求'),(4,5,'访问')])) ,refs=['EFB','L-F','L-S','PAD'])

S(c,'设计原则与技术基线',
P('围绕数据来源组织职责','''本系统采用“一个业务事实，一个明确所有者”的数据组织原则。航班输入由本地航班模型拥有，性能结果由计算器生成，实际飞机状态由宿主提供，界面偏好由持久化设置管理。其他模块使用投影视图，而不是建立另一个可独立修改的副本。

这一原则体现在确认与映射的关系中。工作台先形成完整 Flight，确认成功后由 applyToEfb 生成原生兼容数据。原生仪表盘读取映射结果，但不会反过来变成第二个航班主记录。燃油目标的反向读取也通过明确动作进行，使用户可以区分“计划变了”与“宿主状态更新了”。

数据边界还决定错误的处理位置。输入格式错误在表单或文件解析处报告；超出模型范围在计算器入口报告；宿主不可达在适配层报告；资料服务未授权在资料页面报告。把所有错误都交给全局异常页面会丢失业务语义，也会使本来可以继续的功能被一并中断。''',diagram=D('entity','事实所有者与投影关系',[['Flight','航班输入','确认签名'],['Result','输入快照','计算值与版本'],['原生 Store','兼容航班','页面展示状态'],['Host Snapshot','当前状态','采样语义']],[(0,1,'计算'),(0,2,'投影'),(3,2,'观测')]),table=T('事实|所有者|其他模块的使用方式','航班输入|本地领域状态|读取或经编辑动作修改\n派生质量|weights 函数|按当前输入重新计算\n计算结果|calculate 返回值|只读显示、归档、导出\n实际状态|宿主|采样后显示\n用户偏好|设置存储|读取并应用')),
P('模块化与可替换性','''界面层与计算层之间使用普通数据对象连接。计算函数不依赖 React 组件、DOM 元素或浏览器控件，输入和输出可序列化。这使相同计算既能服务屏幕，也能服务文件报告，并便于在不启动界面的情况下分析算法行为。

机型差异通过配置和上下文注入。原生 AircraftContext 提供计算器与设置能力，UniversalConfigProvider 装载机型、客舱和平板配置。本地参考计算使用独立资料包，资料包包含机型身份、重量范围、表格、版本和不支持的能力。框架与资料由此具有不同的变更频率。

宿主替换采用适配层策略。浏览器版模拟必要的 SimVar、Coherent 和更新事件；后续真实后端可以提供相同职责的实现。替换的对象是数据与命令的连接方式，而不是把一套页面复制为另一套页面。扩展接口的具体设计见第 5 章。''',table=T('可替换对象|稳定接口|变化内容','性能资料包|Flight 与 Result 的语义|表格、限制、配置身份\n宿主实现|读变量、写目标、订阅事件|MSFS、本地开发或其他后端\n资料服务|机场、天气、航图领域对象|提供商与认证机制\n持久化实现|读取、保存、迁移|浏览器存储或后端数据库\n界面组件|页面输入输出与状态动作|布局、语言、交互样式'),diagram=D('layers','稳定领域接口隔离变化点',['页面与交互组件','领域模型：Flight / Result / Profile','稳定契约：计算 / 存储 / 宿主 / 资料','可替换实现：本地存储、模拟器、外部资料'])) ,
P('版本基线与实现范围','''本书的源码分析固定在 Headwind 提交 41eace79ed442696a6361dc72947954c9a6cf5cb 及其 FlyByWire 子模块提交 1bf4b8edccf84d0fb83d0eb15e42f2c773e09582。固定提交用于解释模块关系和实现细节；在线产品文档用于理解功能概念，其更新节奏与源码基线不同。

本地扩展包含航班编辑、JSON 文件、重量确认、参考计算、历史和 HTML 报告。启动修订增加了浏览器自动开机及休眠唤醒提示。原生 A339X 入口仍未启用完整起飞性能计算器；本地标签提供的是独立参考服务，二者在架构上保持区分。

本书以运行基线为主要说明对象。针对跨设备存储、真实后端会话和命令回执提出的接口，明确归入扩展设计。这样既能描述可演示系统，又能给后续工程提供清晰的连接方式，而不把设计目标写成已经部署的功能。''',table=T('构成|版本或位置|说明','Headwind|41eace79…|A339X 机型覆盖\nFlyByWire|1bf4b8ed…|共享 EFB 与 SDK\n本地资料包|profileVersion 1.0.0|A330-941 / Trent 7000\n本地计算内核|engineVersion 1.0.0|参考算术与范围检查\n运行宿主|browser-development|本机变量及事件适配\n真实后端|扩展接口设计|本交付尚未连接'),diagram=D('components','本书描述对象的组成',['固定共享源码','A339X 覆盖','本地宿主','本地业务扩展','参考资料包','可运行 EFB'],[(0,5,'共享组件'),(1,5,'机型配置'),(2,5,'运行环境'),(3,5,'新增业务'),(4,3,'数据')])) ,
P('技术说明与使用说明的阅读关系','''总体设计回答系统由什么组成以及模块怎样协作。详细设计把业务职责落实到对象、函数、页面和数据字段。关键技术解释容易产生隐蔽错误的机制，例如单位归一化、确认签名、异步回读和缓存失效。操作说明则从使用者可以看到的界面出发，不要求读者先理解内部类名。

同一个对象在不同部分具有不同描述粒度。例如，Flight 在数据架构中是一个聚合，在本地航班章节中是编辑和确认的输入，在操作章节中则表现为航班号、机场、旅客和燃油字段。编号和图注把这些描述连接起来，避免操作章节重复整段实现分析。

公式中的数值示例取自本地人工样例。凡涉及速度或着陆距离，本书说明的是源码算法及软件输出，适用范围在对应算法章集中说明。参数、单位、表格来源与输出性质始终成组出现，防止示例脱离上下文后被误读。''',diagram=D('tree','按问题查阅本书',['技术方案与操作说明书',['总体设计','架构 / 数据 / 接口','部署 / 界面'],['详细设计','业务模块','输入 / 输出 / 机制'],['关键技术','状态一致性','可靠性与工程实现'],['操作说明','页面与字段','步骤 / 结果 / 问题']]),table=T('读者问题|主要章节|辅助材料','系统怎样组成|第 2 至 6 章|架构图与部署图\n某功能怎样实现|第 7 至 15 章|对象、接口与状态图\n结果为何失效|第 10、16 章|签名与状态转换\n软件怎样操作|第 18 至 22 章|实际程序截图\n字段如何交换|第 4、5 章及附录|数据字典与 JSON 示例')) ,refs=['HW','FBW','L-B','L-D'])

c=C(2,'系统总体架构','第一篇  系统总体设计')
S(c,'逻辑分层与组件职责',
P('五层逻辑结构','''系统逻辑上分为呈现、应用、领域、适配和基础资源五层。呈现层负责页面与控件；应用层把用户动作组织为编辑、确认、计算、归档等用例；领域层定义数据与规则；适配层连接原生 Store、宿主及资料服务；基础资源层提供文件、浏览器存储和静态资源。

分层是职责划分，不意味着每层都必须是独立进程。当前浏览器版的大多数逻辑运行在同一个 JavaScript 上下文中，静态服务只分发文件。采用逻辑分层仍有价值：计算不需要知道按钮颜色，文件解析不需要知道模拟器变量名称，页面不需要逐一处理油箱体积转换。

依赖方向从界面向稳定的领域模型收敛。领域函数返回结构化值和错误集合，页面将其转换为文字和样式。适配层是外部语义进入系统的位置，也是单位、类型和来源转换的主要位置。''',diagram=D('layers','EFB 五层逻辑架构',['呈现层：Dashboard / LocalFlight / Performance / Ground','应用层：编辑、确认、计算、归档、导入导出','领域层：Flight、Result、Profile、重量与参考算法','适配层：原生 Store 映射、宿主 API、资料服务','基础资源：localStorage、JSON、静态文件、浏览器'])),
P('组件职责分配','''本地扩展以四个文件组形成一个较小的垂直业务切片。flight.ts 承担数据类型、校验、质量关系、插值和单位转换；state.ts 承担状态发布、确认、结果有效性、原生映射与报告；LocalPages.tsx 承担页面与用户动作；资料 JSON 提供与代码版本分离的常量。

原生模块仍保留各自的 Store 切片和宿主访问逻辑。本地扩展没有把所有原生状态搬入一个新的 Store，而是通过明确的映射接入。这降低了对上游组件的改动量，同时留下一个需要说明的边界：原生页面拥有一些临时状态，本地 Flight 不覆盖这些状态的全部生命周期。

组件间传递业务对象或状态动作，不传递页面 DOM。报告模块从 Result 读取数据，不能从某个文本框中反向抓取“当前结果”。由此，报告的正确性与页面布局调整解耦。''',table=T('组件|输入|输出或副作用','flight.ts|Flight、Profile|错误集合、质量、Result\nstate.ts|编辑与确认等动作|本地 State、持久化与映射\nLocalPages.tsx|State、用户输入|调用应用动作并渲染反馈\na339-reference.json|固定资料内容|机型身份、范围、表格\n原生 Store|映射动作与宿主值|页面共享状态\nsimulator-shim.ts|变量读写、事件注册|开发宿主行为\nserver.cjs|HTTP 文件请求|页面、脚本、字体及配置'),diagram=D('components','本地业务切片内部依赖',['LocalPages.tsx','state.ts','flight.ts','资料包 JSON','原生 Store','本机存储'],[(0,1,'动作 / 状态'),(1,2,'规则调用'),(2,3,'读取'),(1,4,'确认映射'),(1,5,'保存')])) ,
P('为什么保留原生组件','''Headwind 与 FlyByWire 已提供成熟的导航结构、机型设置、检查单组件、燃油与载重界面。保留这些组件使本地系统继承一致的视觉和操作习惯，也避免为一项离线航班功能重新实现整套平板界面。

复用不等于直接把所有机型功能打开。共享库中可以存在其他机型的计算器或页面，A339X 的入口上下文决定实际启用内容。例如，A339X 使用自身着陆计算器，而原生完整起飞计算器入口为空。新参考计算以独立路由加入，保持其数据来源和能力范围可辨认。

这种组合设计的代价是需要一个明确的兼容层。原生代码采用既有字段命名和数据形状，本地领域模型采用更直接的数字与单位。兼容层承担转换，而不是要求全部新代码沿用历史命名。''',table=T('设计选择|带来的作用|需要保持的边界','复用导航与控件|一致的操作方式|新增入口保持原生结构\n复用原生 Store|仪表盘及地面页面可继续工作|确认时整体映射\n独立本地领域模型|规则不受旧字段格式牵制|兼容层转换数字与字符串\n独立资料包|数据与界面分别更新|版本参与结果身份\n宿主适配|普通浏览器可运行|样例状态与真实状态分开'),diagram=D('components','框架复用与机型注入',['共享 flyPad 框架','A339X AircraftContext','本地新增页面','原生页面集合','机型配置','宿主接口'],[(0,3,'组件结构'),(1,3,'计算器 / 能力'),(2,0,'路由嵌入'),(4,1,'机型数据'),(5,3,'状态与控制')])) ,
P('组件边界中的失败隔离','''失败隔离围绕业务依赖展开。外部航图加载失败只影响航图内容；航班 JSON 校验失败保留当前航班；当前参考计算不受支持时保留输入和原因；静态资源启动失败则属于整个应用无法装载的情况。不同失败的影响面因此不同。

页面级错误提示用于可恢复的业务问题。全局错误边界用于组件渲染异常，启动入口的错误面板用于模块装载异常。把业务拒绝与程序异常区分开，既能保留用户工作，也能让维护者定位到正确层次。

当前实现中，本地存储失败会形成 storageError 并提示导出文件；文件解析失败不会部分写入 Flight。后续资料服务增加缓存时，同样需要保留“内容存在”和“内容当前可用”两个判断，不能因为缓存中有对象就隐去错误来源。''',diagram=D('tree','失败影响面的分级',['失败范围',['应用装载','入口脚本 / 资源','显示启动错误'],['业务模块','模型不支持 / 输入错误','保留输入并解释'],['外部资料','连接 / 授权 / 内容','局部空态或缓存'],['存储出口','容量 / 权限','提示文件导出']]),table=T('失败位置|保留内容|用户反馈','JSON 解析|当前航班完整状态|格式或字段错误\n输入校验|当前草稿|字段原因\n计算范围|输入与辅助结果|unsupported 及原因\n持久化|内存中的当前状态|保存失败提示\n外部服务|本地业务能力|连接或账户状态\n入口模块|本机文件和保存数据|启动失败文字')) ,refs=['L-F','L-S','L-U','EFB','L-H'])

S(c,'运行组件与依赖装配',
P('从静态入口到原生平板','''浏览器首先装载 index.html 和 Vite 生成的模块入口。bootstrap.ts 建立逻辑画布、状态提示和窗口缩放，然后装载宿主替身及原生 EFB 入口。宿主接口必须先于原生模块存在，因为导入阶段就可能读取全局类型或注册事件。

原生入口创建 AircraftContext，提供 A339X 着陆计算器、设置能力和机型参数，再渲染 EfbWrapper。包装组件装载机型、客舱和平板配置以及检查单。Provider 将共享 Store 注入组件树，MemoryRouter 管理页面层次。

浏览器启动通过 AceInitialized 事件触发本地 render 适配器。随后 Efb 进入约 2.5 秒的原生加载状态，再显示首页。自动开机只属于本地构建适配；原生模拟器中的电源语义仍由其宿主环境决定。''',diagram=D('sequence','浏览器版启动时序',['浏览器','bootstrap / shim','原生入口','EfbWrapper'],[(0,1,'加载入口模块'),(1,1,'建立全局宿主 API'),(1,2,'动态装载 EFB'),(2,3,'配置 Context 与 Provider'),(1,2,'AceInitialized'),(3,3,'读取配置和检查单'),(3,0,'加载画面 → 首页')])) ,
P('上下文与提供器的职责','''组件树中的 Provider 为子组件提供共享能力。Redux Provider 提供页面共享状态；AircraftContext 提供机型能力；故障提供器提供故障编排对象；模态框提供器统一承载弹窗；航图认证提供器保存认证相关上下文。这些能力通过 React 的依赖注入方式下传，避免逐层传递大量参数。

Provider 与领域数据所有者并不总是一一对应。AircraftContext 适合放置相对稳定的计算器和能力开关，航班草稿则高频变化，不适合塞进同一个机型上下文。将稳定能力与高频状态分开，可以缩小重渲染范围，也使组件依赖更清楚。

机型配置异步装载，因此页面不能把初次渲染时的空配置当作最终配置。配置提供器负责读取，Store 负责保存，业务页面再从已装载配置中取得舱段和限制。初始化依赖在启动流程中集中说明，减少页面各自猜测“配置是否已经准备好”的情况。''',table=T('共享上下文|适合承载的内容|典型使用者','AircraftContext|计算器、机型能力、设置项|性能和设置页面\nRedux Provider|页面切片、配置、航班投影|仪表盘及原生页面\n故障提供器|故障定义与编排对象|故障选择页面\nModalProvider|模态框容器及打开动作|提示、确认和异常页面\nNavigraphAuthProvider|认证过程与账户状态|航图页面\n本地 useLocal|草稿、确认、结果与历史|本地航班及参考页面'),diagram=D('tree','组件树中的依赖注入',['AircraftContext',['EfbWrapper','配置读取','检查单读取'],['Redux / EfbInstrument','故障与模态框提供器','MemoryRouter'],['业务页面','机型能力','共享状态 / 本地状态']])) ,
P('同步状态与异步资源','''用户编辑字段时，派生重量可以在同一轮界面更新中计算；配置文件和外部资料则通过异步请求取得。同步路径追求确定性，异步路径需要表示等待、成功和失败。把两者混合在一个“是否加载”布尔值中，会使用户无法分辨是输入不完整，还是服务仍在返回。

原生配置从本机静态目录读取，因此部署后仍使用 HTTP 请求语义，但并不意味着它依赖外网。本地航班确认把完整数据提交到 Store，也不同于逐字段请求远程后端。架构图中的网络边界只出现在实际跨进程或跨主机的连接上。

初始化顺序中最重要的依赖是：宿主 API 先建立，原生模块随后导入，组件渲染后装载配置，业务页面使用结果。浏览器自动开机不承担配置文件校验职责；配置缺失仍应作为独立问题定位。''',table=T('处理类型|触发方式|完成语义','派生重量|输入变化|函数返回即得到当前值\n本地确认|用户动作|签名与原生投影更新\n配置读取|组件初始化|Promise 返回 JSON 并写入 Store\n宿主写入|页面动作|写入请求完成，状态另行回读\n外部资料|页面或用户刷新|服务响应及数据转换完成\n报告生成|用户导出|当前有效 Result 序列化'),diagram=D('lanes','启动时的同步和异步路径',[['入口线程','宿主建立','动态导入','触发渲染'],['组件状态','初始 Store','加载状态','首页显示'],['异步资源','配置请求','解析配置','Store 更新']])) ,
P('本地服务的职责收敛','''server.cjs 是静态文件服务，而不是业务计算后端。它把请求路径映射到 dist 目录，为 HTML、JavaScript、样式、字体和配置设置对应媒体类型。无扩展名路径回退到入口页，以便浏览器打开应用地址；业务页面的实际路由仍由 MemoryRouter 管理。

服务绑定 127.0.0.1，默认端口 9697。/__health 返回应用标识、运行模式及源码基线，用于判断端口上是否为本 EFB 服务。健康响应只说明静态宿主进程可达，不能代表某个资料提供商或真实模拟器已经连接。

这种职责收敛让日常启动不依赖源码编译工具。构建阶段输出 dist，运行阶段只需 Node.js 分发已有资源。后续增加后端计算或会话服务时，可单独部署对应进程，不必把业务逻辑塞进当前静态文件处理函数。''',diagram=D('deployment','本地运行进程与端口',['浏览器\nReact EFB','127.0.0.1:9697\nNode 静态服务','磁盘 dist\n脚本 / 配置 / 字体','浏览器站点存储\n航班与历史'],[(0,1,'HTTP GET'),(1,2,'文件读取'),(0,3,'本机保存')]),table=T('入口|响应内容|职责','/|应用入口 HTML|启动页面\n/assets/*|构建后的脚本与样式|客户端逻辑\n/VFS/config/*|机型与客舱配置|静态配置\n/Fonts/*|字体文件|文字显示\n/__health|JSON 健康信息|进程识别')) ,refs=['L-H','L-B','EFB'])

S(c,'核心业务数据流',
P('输入到结果的主数据流','''业务主链由 Flight 开始，以 Result 和可读报告结束。用户输入在编辑阶段形成草稿；validate 检查结构、格式和业务范围；weights 计算质量关系；确认动作记录输入签名；calculate 在同一资料包下生成结果。各阶段均以对象为边界，因此可以描述清楚哪一步产生了哪一种信息。

校验与支持范围判断是两层规则。格式正确的湿跑道航班是合法输入，但当前参考模型不支持湿跑道速度修正。这类输入进入 unsupported 状态，而不是伪装成文件格式错误。合法性与可计算性分开后，错误提示也更符合用户理解。

结果携带输入快照、时间、资料包版本和内核版本。页面、历史及报告读取同一快照。计算后继续修改草稿时，旧结果对象可以仍保存在内存中用于说明，但有效结果选择器不再返回它。''',diagram=D('pipeline','Flight 到 Result 的处理链',['草稿 Flight','结构与业务校验','确认签名','模型范围判断','计算 Result','显示 / 历史 / 报告']),table=T('阶段|主要函数|产生的信息','结构校验|validate / parseFlight|字段错误集合\n派生质量|weights|payload、ZFW、ramp、TOW\n确认|confirmFlight|当前输入签名\n计算|calculate|结果及支持范围状态\n有效性选择|currentResult|当前可使用的结果或 null')),
P('本地模型到原生页面的投影','''本地 Flight 使用明确的数值字段和 SI 质量单位，而原生航班切片包含历史兼容字段、字符串重量和展示用资料。applyToEfb 从原生初始结构开始构造完整投影，再填入本地航班信息。这样可保留原生组件预期的嵌套对象，避免只更新几个字段后留下不完整结构。

投影包含机场、航班号、重量、燃油及可读 loadsheet。当前本地实现还填入固定的展示时刻和部分占位值，因此这些字段的含义是兼容显示，不代表外部签派计算。数据字典把实际输入字段、派生字段和展示占位字段分别说明。

确认还会重置燃油与载重导入标志，使原生页面能够重新接受计划。原生目标被手工修改时，宿主事件撤销本地结果有效性。投影与失效共同形成一个有方向的同步边界，而不是无限双向绑定。''',diagram=D('entity','领域对象与原生投影',[['Flight','number / from / to','pax / rampKg / taxiKg'],['SimBriefData 兼容结构','flightNum / departingAirport','weights / fuels / loadsheet'],['宿主目标','FUEL_DESIRED','ZFW_DESIRED / GW_DESIRED']],[(0,1,'applyToEfb'),(0,2,'确认时设置')]),table=T('本地值|原生投影|转换含义','number|flightNum|保留航班标识\nfrom / to|departingAirport / arrivingAirport|机场代码\npax|weights.passengerCount|数字转字符串\nweights(f).zfw|estZeroFuelWeight|派生质量转字符串\nrampKg|fuels.planRamp|计划停机坪燃油\nrampKg - taxiKg|fuels.planTakeOff|计划起飞燃油')),
P('地面目标变化的数据回路','''地面页面允许用户直接改变燃油或载重目标。这些变化不应悄悄保留旧参考结果，因为旧结果的输入可能已经与新的地面准备不一致。本地宿主在目标变量变化时发出 local-ground-change，状态层将 groundChanged 置为 true。

该事件只表达“目标域发生了变化”，不自动重写整个航班。工作台提供读取燃油目标的明确动作，用于把选定的目标值带回 rampKg。载重分布包含舱段与座位等更复杂的信息，当前实现没有把所有分布自动反向解析为一个新的 Flight。

通过显式回读，用户能看到计划发生了什么变化，并重新确认。相较于双向自动绑定，这种设计多了一次可见动作，但避免地面控制、计划草稿和计算输入在没有提示的情况下互相覆盖。''',diagram=D('sequence','目标改变引起结果失效',['地面页面','宿主适配','本地状态','航班工作台'],[(0,1,'写入 DESIRED 变量'),(1,2,'local-ground-change'),(2,2,'groundChanged = true'),(2,3,'显示重新确认提示'),(3,1,'读取燃油目标'),(3,2,'更新草稿并确认')]),table=T('数据方向|发生时机|处理方式','计划 → 原生目标|确认航班|applyToEfb 显式设置\n原生目标 → 失效状态|目标发生变化|撤销当前结果资格\n燃油目标 → 航班|点击读取目标|更新 rampKg 草稿\n航班 → 新结果|重新确认后计算|生成新签名和快照')),
P('报告、历史与文件的出口','''系统有三种不同的数据出口。航班 JSON 保存可再次编辑的输入；历史保存当时的 Result 及其输入快照；HTML 报告保存可阅读和打印的计算记录。文件名或扩展名只是表现形式，真正决定用途的是所序列化的对象。

报告生成前调用 currentResult，因此它只能导出与当前输入、确认状态和资料包一致的 reference-only 结果。航班文件则可以作为输入交换，不包含“本次计算仍有效”的承诺。历史恢复也只取 input，继续沿用草稿到确认的正常路径。

HTML 中的用户文本经过字符转义，避免航班号或航路文字被解释为标签。下载使用临时 Blob URL，并在动作完成后释放。打印打开独立文档窗口；如果浏览器阻止弹窗，用户仍可使用 HTML 文件出口。''',diagram=D('components','三种数据出口及其用途',['Flight 输入','Result 快照','航班 JSON','本机历史','HTML 报告','打印文档'],[(0,2,'输入交换'),(1,3,'保存记录'),(1,4,'格式化'),(4,5,'打印'),(3,0,'恢复输入')]),table=T('出口|包含内容|再次使用方式','航班 JSON|schemaVersion 与 Flight 字段|导入后重新确认\n本机历史|最多 20 条 Result|恢复输入并重算\nHTML 报告|结果、输入快照、版本及范围|浏览器阅读或打印\n打印输出|报告当前画面|文件归档或纸面阅读')) ,refs=['L-F','L-S','L-U'])

S(c,'扩展架构与演进边界',
P('真实宿主接入的架构位置','''真实模拟器接入位于适配层。EFB 的航班模型和计算器不直接读取飞行动力学内存，也不直接解析机型 XML。后端负责装载模型、运行系统并产生状态，适配层把这些状态转换为前端需要的快照，并把前端命令转换为宿主操作。

扩展设计把读模型与写模型分开。快照是对当前状态的描述，命令是希望执行的动作。命令提交后可以返回“已接受”，而动作完成需要后续状态或回执来表达。该区分尤其适用于推回、加油和设备连接等持续过程。

本地浏览器替身仍可用于界面开发，但与真实后端适配器使用不同的运行标识。会话建立时确定 aircraftId、modelVersion 和运行模式，页面持续展示连接身份，避免用户把开发样例与真实后端快照混看。''',diagram=D('deployment','真实宿主接入位置（扩展设计）',['EFB 浏览器','宿主适配接口','会话与状态服务','模拟器 / 飞行模型','机型模型与配置'],[(0,1,'领域请求'),(1,2,'快照 / 命令'),(2,3,'唯一控制入口'),(4,3,'模型装载')]),table=T('接口类别|方向|主要内容','会话|双向|机型、版本、连接身份\n状态快照|后端 → EFB|值、单位、时间及质量\n命令|EFB → 后端|目标、参数、请求标识\n命令回执|后端 → EFB|接受、拒绝、执行与完成\n能力清单|后端 → EFB|可读变量及可用命令')),
P('多机型配置的分离方式','''多机型支持不是把不同机型的限制数值放进一个大条件分支。稳定的页面框架读取机型能力描述，机型资料包提供质量限制、布局和计算数据，宿主适配映射到该机型使用的变量。三者以机型身份和版本关联。

例如，燃油页面需要油箱结构，载重页面需要站位和座位布局，性能页面需要可用计算器。某机型未提供某项能力时，界面可以不显示入口，或显示有解释的不可用状态。不能因为共享库内存在一个计算器类，就推断所有机型都适用。

资料包与航班文件绑定 profileId。导入文件时检查身份，计算时把资料包整体纳入签名。切换机型后，旧输入、旧确认和旧结果之间的关系必须重新建立，避免同一个航班号掩盖底层机型已经改变的事实。''',diagram=D('entity','机型身份连接配置与业务',[['Aircraft Identity','aircraft / engine','profileId'],['Profile','限制 / 表格 / 版本','支持能力'],['Layout','客舱 / 油箱','界面选项'],['Host Mapping','变量名 / 单位','命令映射']],[(0,1,'匹配'),(0,2,'选择'),(0,3,'选择')]),table=T('变化内容|配置归属|前端使用方式','发动机与机型身份|Profile|文件与结果身份检查\n座位和货舱|客舱配置|载重布局渲染\n油箱容量|机型配置|燃油图及容量显示\n计算方法|计算器注册|按能力调用\n宿主变量|适配映射|单位及字段转换')),
P('服务化扩展与本地优先','''当航班需要跨设备协作时，可以在现有应用层下增加后端存储适配，而不改变 Flight 的业务含义。客户端仍保留当前草稿，服务端保存版本化记录。保存动作携带预期版本，服务端只在版本匹配时更新，以识别另一设备已经提交的修改。

本地优先意味着用户输入不会以网络请求成功为前提才能显示。草稿先保存在本机，远端同步有独立状态。离线期间产生的更改进入待同步队列，恢复连接后按明确策略处理冲突。此处是扩展架构，当前版本仍使用单浏览器站点存储。

计算服务也可以独立部署，但结果必须继续包含输入快照与资料版本。把计算移到远端并不能省略结果身份；网络延迟反而增加了旧响应覆盖新输入的风险。因此远端响应与当前输入签名的匹配是服务化后仍需保留的规则。''',diagram=D('sequence','版本化远端保存（扩展设计）',['客户端 A','保存服务','版本库','客户端 B'],[(0,1,'save(expectedVersion = 7)'),(1,2,'比较并写入 v8'),(1,0,'返回 version = 8'),(3,1,'save(expectedVersion = 7)'),(1,3,'版本冲突及当前 v8')]),table=T('当前结构|扩展位置|保持不变的语义','单机草稿|增加同步适配器|用户编辑仍立即反馈\nlocalStorage|增加后端版本库|Flight 的字段含义\n本地计算函数|增加计算服务端点|输入和版本决定结果\n有限本机历史|增加服务端归档|历史恢复不自动确认')),
P('架构决策及其影响','''本系统选择较薄的本地宿主和较集中的领域模型，是为了让浏览器运行、上游复用和业务扩展之间的关系保持可解释。这个选择适合当前单机功能范围，但不把分布式事务、组织权限和远端协作隐藏在“以后自然支持”的表述中。

每个架构决策都有明确后果。MemoryRouter 使内嵌仪表导航不依赖地址栏，但浏览器深链接不能自动恢复业务标签；JSON 签名便于检查完整输入，但需要稳定的资料身份；本机历史使离线操作简单，但不提供跨设备共享。设计文档同时说明获得的能力与对应代价。

后续工程应围绕稳定边界演进：增加宿主实现、资料包或持久化适配，而不是在页面中直接插入新的后端调用。这样可以保持操作界面与底层服务独立变化，并使问题定位落到清楚的职责边界。''',table=T('架构决策|主要理由|直接影响','保留原生 flyPad|复用完整业务界面|需要兼容映射层\n独立 Flight 模型|明确单位与业务语义|旧结构作为投影\n纯函数参考计算|结果可重现、便于解释|不读取隐式页面状态\n本机静态服务|运行依赖简单|业务在浏览器执行\nMemoryRouter|适配仪表内部导航|URL 不代表业务标签\n完整输入签名|识别资料和输入变化|变更后撤销结果资格\n显式地面回读|避免双向覆盖|用户重新确认计划'),diagram=D('components','扩展沿稳定边界进行',['页面框架','应用动作','领域模型','宿主适配','资料适配','存储适配'],[(0,1,'用户意图'),(1,2,'业务规则'),(1,3,'控制与观测'),(1,4,'资料请求'),(1,5,'保存与恢复')])) ,refs=['L-H','L-F','L-S','EFB'],scope='本节真实后端、协同及多机型服务化内容为扩展设计')
